package com.siiiweb.user.controller;import com.siiiweb.common.*;import com.siiiweb.user.entity.User;import com.siiiweb.user.repository.UserRepository;import org.springframework.data.redis.core.StringRedisTemplate;import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;import org.springframework.web.bind.annotation.*;import java.util.*;import java.util.concurrent.TimeUnit;
@RestController public class UserController{private final UserRepository repo;private final StringRedisTemplate redis;private final BCryptPasswordEncoder encoder=new BCryptPasswordEncoder();public UserController(UserRepository r,StringRedisTemplate t){repo=r;redis=t;}
@PostMapping("/api/admin/login") public Map<String,Object> login(@RequestBody Map<String,String> body){String u=body.getOrDefault("username","admin"),p=body.getOrDefault("password","demo123456");User user=repo.findByUsername(u).orElseGet(()->{User x=new User();x.username="admin";x.password=encoder.encode("demo123456");return repo.save(x);});if(!encoder.matches(p,user.password))throw new RuntimeException("bad credentials");String token=JwtUtil.create(u);redis.opsForValue().set("token:"+u,token,2,TimeUnit.HOURS);return Map.of("token",token,"user",Map.of("username",u,"role",user.role));}
@PostMapping("/api/admin/refresh") public Map<String,String> refresh(@RequestHeader("Authorization") String h){String u=JwtUtil.parse(h.substring(7));String token=JwtUtil.create(u);redis.opsForValue().set("token:"+u,token,2,TimeUnit.HOURS);return Map.of("token",token);} 
@GetMapping("/api/about") public Map<String,Object> about(){return Map.of("name","杨怡涵","major","大数据技术","skills",List.of("Linux","Docker","K8s","Vue3","Spring Cloud","Redis","RabbitMQ"));}
@PutMapping("/api/admin/about") public ApiResponse<?> update(@RequestBody Map<String,Object> body){return ApiResponse.ok(body);} }
